{
  "investigate": [
    {
      "tool": "sql",
      "query": "SELECT service, SUM(open) as open_connections FROM db_sessions GROUP BY service ORDER BY open_connections DESC",
      "why": "Identify which services are holding the most database connections to pinpoint the source of pool exhaustion."
    }
  ],
  "hypotheses": [
    {
      "service": "database",
      "kind": "resource_exhaustion",
      "mechanism": "The database connection pool is exhausted, but the issue is not uniform across all clients; payment-service and worker are the primary sources of connection demand, while order-service and workflow are unaffected.",
      "supporting": ["E2", "E8", "E9", "E10", "E23", "E24"],
      "refuting": ["E11"],
      "explains": ["M2_error_burst", "M3_dead_letters", "M4_db_pool_pressure", "E3", "E4", "E5", "E6", "E7"],
      "repair_plan": [
        {
          "action": "restart_service",
          "params": {
            "service": "database"
          }
        }
      ]
    }
  ],
  "summary": "Database connection pool exhaustion is driven by payment-service and worker, causing their errors and dead letters, while order-service and workflow remain unaffected."
}
